html, body { margin: 0; padding: 0; }

body {
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(138, 180, 255, 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 10%, rgba(255, 209, 102, 0.06), transparent 60%),
    var(--bg);
  color: var(--text);
  font: 16px/1.6 system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main { flex: 1; }

.wrap {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -100px;
  background: var(--accent);
  color: #0b0d12;
  padding: 0.6rem 0.9rem;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 0.5rem; }

/* Header */
.page-header {
  padding: 3.5rem 0 2rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2.5rem;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.78rem;
  color: var(--accent);
  margin: 0 0 0.5rem;
  font-weight: 600;
}
h1 {
  font-size: clamp(2rem, 4vw, 2.75rem);
  margin: 0 0 0.75rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.lede {
  color: var(--text-muted);
  margin: 0;
  font-size: 1.05rem;
  max-width: 56ch;
}

h2 {
  font-size: 1.35rem;
  margin: 0 0 1.25rem;
  letter-spacing: -0.01em;
}

/* FAQ items */
.example {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 12px;
  margin-bottom: 0.75rem;
  overflow: hidden;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.example:hover {
  border-color: var(--border-strong);
}
.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--border-strong);
  background: var(--bg-elev-2);
  box-shadow: var(--shadow);
}

.faq-question {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
}

.faq-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.25rem;
  background: transparent;
  color: inherit;
  border: 0;
  font: inherit;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  border-radius: 12px;
}
.faq-trigger:hover .faq-label { color: var(--accent-strong); }

.faq-trigger:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-label { flex: 1; }

.faq-icon {
  flex: 0 0 auto;
  width: 1.4rem;
  height: 1.4rem;
  position: relative;
  border: 1px solid var(--border-strong);
  border-radius: 50%;
  transition: transform 0.25s ease, background 0.2s ease, border-color 0.2s ease;
}
.faq-icon::before,
.faq-icon::after {
  content: "";
  position: absolute;
  background: var(--text);
  inset: 0;
  margin: auto;
  transition: transform 0.25s ease, background 0.2s ease;
}
.faq-icon::before { width: 0.7rem; height: 2px; }
.faq-icon::after  { width: 2px; height: 0.7rem; }

.faq-trigger[aria-expanded="true"] .faq-icon {
  background: var(--accent);
  border-color: var(--accent);
  transform: rotate(180deg);
}
.faq-trigger[aria-expanded="true"] .faq-icon::before,
.faq-trigger[aria-expanded="true"] .faq-icon::after {
  background: #0b0d12;
}
.faq-trigger[aria-expanded="true"] .faq-icon::after {
  transform: scaleY(0);
}

.details {
  padding: 0 1.25rem 1.2rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}
.details p {
  margin: 1rem 0 0;
}
.details em { color: var(--text); font-style: italic; }

/* Footer */
.page-footer {
  margin-top: 4rem;
  padding: 1.5rem 0;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.9rem;
  text-align: center;
}
.page-footer p { margin: 0; }

/* Forced colors */
@media (forced-colors: active) {
  .example { border: 1px solid CanvasText; }
  .faq-trigger:focus-visible { outline: 3px solid Highlight; }
  .faq-icon { border-color: CanvasText; }
  .faq-icon::before, .faq-icon::after { background: CanvasText; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
  }
}
