AssistantMessageToolRequest(name='create', tool_call_id='toolu_01EJ2mzAzrzuA9fvR46eqQYm', arguments={'file_text': "// Initialize FAQ disclosure widgets.
// Panels start collapsed via JS so content stays visible without JS (e.g. reader mode).
(function () {
  var triggers = document.querySelectorAll('.faq-trigger');

  triggers.forEach(function (btn) {
    var item = btn.closest('.example');
    var panel = item ? item.querySelector('.details') : null;
    if (!panel) return;

    btn.setAttribute('aria-expanded', 'false');
    if (!panel.id) {
      panel.id = 'faq-panel-' + Math.random().toString(36).slice(2, 9);
    }
    btn.setAttribute('aria-controls', panel.id);
    panel.hidden = true;

    btn.addEventListener('click', function () {
      var open = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!open));
      panel.hidden = open;
    });
