AssistantMessageToolRequest(name='create', tool_call_id='toolu_01LdHa5uvX9sDWDCv33aHRyn', arguments={'file_text': "const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const axeSource = fs.readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8');

async function run(label, mutate) {
  const html = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  const css = fs.readFileSync(path.join(__dirname, 'styles.css'), 'utf8');
  const js = fs.readFileSync(path.join(__dirname, 'script.js'), 'utf8');
  const dom = new JSDOM(html, { runScripts: 'outside-only', pretendToBeVisual: true, url: 'file://' + __dirname + '/' });
  const { window } = dom;
  // Inject CSS so color-contrast can run
  const style = window.document.createElement('style');
  style.textContent = css;
  window.document.head.appendChild(style);
  // Run init script
  window.eval(js);
  if (mutate) mutate(window);
  // Inject axe and run
  window.eval(axeSource);
  const results = await window.axe.run(window.document, {
    resultTypes: ['violations'],
  });
  console.log(`\n=== ${label} ===`);
  console.log('Violations:', results.violations.length);
  for (const v of results.violations) {
    console.log('-', v.id, '|', v.impact, '|', v.help);
    for (const n of v.nodes) {
      console.log('   ', n.target.join(' '));
      console.log('     ', (n.failureSummary || '').replace(/\n/g, ' '));
